SELECT length('gamma'), upper('gamma'), lower('gamma'), substr('gamma', -2, 1), instr('gamma', 'x_y'), replace('gamma', '', ''), trim('gamma'), ltrim('gamma', 'ab'), hex('gamma'), quote('gamma'), unicode('gamma'), 'gamma' LIKE 'A%', 'gamma' GLOB 'a*', char(66, 691), 'gamma' || 'x_y', 'gamma' < 'x_y', 'gamma' = 'x_y' COLLATE NOCASE;
SELECT length('theta'), upper('theta'), lower('theta'), substr('theta', -1, 1), instr('theta', 'kappa'), replace('theta', 'a', '_'), trim('theta'), ltrim('theta', 'ab'), hex('theta'), quote('theta'), unicode('theta'), 'theta' LIKE '%é%', 'theta' GLOB '?', char(90, 427), 'theta' || 'kappa', 'theta' < 'kappa', 'theta' = 'kappa' COLLATE NOCASE;
